import { useCallback, useEffect, useState } from 'react'
import { RotateCcw } from 'lucide-react'

// eslint-disable-next-line react-refresh/only-export-components
export function useRemote<T>(fetcher: () => Promise<T>) {
  const [data, setData] = useState<T | null>(null)
  const [error, setError] = useState('')
  const [busy, setBusy] = useState(true)
  const [revision, setRevision] = useState(0)
  const reload = useCallback(() => setRevision(x => x + 1), [])
  useEffect(() => {
    let active = true
    setBusy(true); setError('')
    fetcher().then(d => { if (active) setData(d) }).catch(e => { if (active) setError(e instanceof Error ? e.message : 'ارتباط برقرار نشد.') }).finally(() => { if (active) setBusy(false) })
    return () => { active = false }
  }, [fetcher, revision])
  return { data, error, busy, reload, setData }
}
export function LoadState({ busy, error, retry }: { busy: boolean; error: string; retry: () => void }) {
  if (error) return <div className="cent-error" role="alert"><p>{error}</p><button className="button button-secondary" onClick={retry}><RotateCcw size={16}/> تلاش دوباره</button></div>
  if (busy) return <div className="cent-loading" role="status"><span className="cent-spinner"/> در حال بارگذاری…</div>
  return null
}

import { PersonalResults } from './PersonalResults'
import { useCallback, useEffect, useRef, useState } from 'react'
import { Link, Navigate, useLocation, useNavigate, useParams, useSearchParams } from 'react-router-dom'
import { ArrowLeft, ArrowRight, BookOpen, CheckCircle2, Clock3, MessageSquare, Sparkles, Target } from 'lucide-react'
import { cent, type ExamAttempt, type ExamOutcome } from '../services/cent'
import { useAppState } from '../state/AppState'
import { LoadState, useRemote } from '../components/CentUI'
import { PageHeader, ProgressBar, StatCard } from '../components/UI'
import type { AnswerMap } from '../types'
import { studyReturnPath } from '../services/study-return'
import { AppearanceControl } from '../components/AppearanceControl'

export function CentDashboard() {
  const remote = useRemote(cent.library)
  const { diagnosticResult, aiAnalysis } = useAppState()
  const recent = remote.data?.progress.slice().sort((a, b) => b.updatedAt.localeCompare(a.updatedAt))[0]
  const document = remote.data?.documents.find(d => d.id === recent?.documentId)
  return <><PageHeader eyebrow="یک قدم در هر روز" title="امروز از کجا ادامه می‌دهی؟" description="فضایی برای یادگیری متمرکز، مرور نوشته‌ها و سنجش مسیرت." action={<Link className="button button-primary" to="/student/content">کتابخانه من <ArrowLeft size={18}/></Link>}/><LoadState {...remote} retry={remote.reload}/><section className="cent-dashboard-lead"><div><span className="pill light"><BookOpen size={16}/> مسیر شخصی تو</span><h2>{document ? document.title : 'اولین صفحه منتظر توست.'}</h2><p>{recent && document ? `آخرین بار تا صفحه ${recent.lastPage} خواندی. یادداشت‌هایت همان‌جا منتظرند.` : 'آموزشت را انتخاب کن، در حاشیه‌اش بنویس و هر بار از همان‌جا ادامه بده.'}</p><Link className="button button-secondary" to={document ? `/student/study/${document.id}` : '/package'}>{document ? 'ادامه مطالعه' : 'انتخاب آموزش'}<ArrowLeft size={17}/></Link></div><div className="cent-dashboard-symbol"><BookOpen/><span>READ / REFLECT / REPEAT</span></div></section><div className="stats-grid"><StatCard icon={<BookOpen/>} label="آموزش‌های کتابخانه" value={remote.data?.trainings.length ?? '—'}/><StatCard icon={<MessageSquare/>} label="یادداشت‌های من" value={remote.data?.notes.reduce((sum, n) => sum + n.count, 0) ?? '—'}/><StatCard icon={<Target/>} label="آخرین نتیجه" value={diagnosticResult ? `${diagnosticResult.percentage}٪` : '—'}/><StatCard icon={<Sparkles/>} label="اشتراک مطالعه" value={remote.data ? remote.data.hasSubscription ? 'فعال' : 'غیرفعال' : '—'}/></div><div className="cent-admin-columns"><section className="card cent-admin-panel"><span className="eyebrow">یادداشت‌های کنار مسیر</span><h2>آنچه یاد گرفته‌ای، همراهت می‌ماند.</h2><p>همه نکته‌هایت را مرور کن؛ حتی اگر اشتراکت تمام شده باشد.</p><Link className="text-link" to="/student/notes">مرور یادداشت‌ها <ArrowLeft size={16}/></Link></section><section className="card cent-admin-panel"><span className="eyebrow">قدم بعدی</span><h2>{aiAnalysis ? 'براساس آخرین ارزیابی تو' : 'مسیرت را بهتر بشناس'}</h2><p>{aiAnalysis?.suggestedNextStep || 'با تعیین سطح، مباحثی را که به مرور بیشتری نیاز دارند پیدا کن.'}</p><Link className="text-link" to="/diagnostic/test">تعیین سطح <ArrowLeft size={16}/></Link></section></div></>
}

export function CentExamPage({ kind = 'diagnostic' }: { kind?: 'diagnostic' | 'simulator' | 'practice' }) {
  const { user, loading, setDiagnostic } = useAppState()
  const [params] = useSearchParams()
  const returnToStudy = studyReturnPath(params.get('returnTo'))
  const catalog = useRemote(cent.curriculum)
  const [course, setCourse] = useState(params.get('course') || '')
  const [topic, setTopic] = useState(params.get('topic') || '')
  const storageKey = `cent:exam:${user?.id}:${kind}:${course}:${topic}`
  const [attempt, setAttempt] = useState<ExamAttempt | null>(null)
  const [answers, setAnswers] = useState<AnswerMap>({})
  const [index, setIndex] = useState(0)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')
  const [remaining, setRemaining] = useState(3600)
  const requestId = useRef(crypto.randomUUID())
  const navigate = useNavigate()
  const location = useLocation()
  useEffect(() => {
    try {
      const saved = JSON.parse(sessionStorage.getItem(storageKey) || 'null') as { attempt: ExamAttempt; answers: AnswerMap } | null
      if (saved && Date.parse(saved.attempt.expiresAt) > Date.now()) { setAttempt(saved.attempt); setAnswers(saved.answers) }
      else sessionStorage.removeItem(storageKey)
    } catch { sessionStorage.removeItem(storageKey) }
  }, [storageKey])
  useEffect(() => { if (attempt) sessionStorage.setItem(storageKey, JSON.stringify({ attempt, answers })) }, [attempt, answers, storageKey])
  useEffect(() => {
    if (!attempt) return
    const tick = () => setRemaining(Math.max(0, Math.floor((Date.parse(attempt.expiresAt) - Date.now()) / 1000)))
    tick(); const timer = window.setInterval(tick, 1000); return () => window.clearInterval(timer)
  }, [attempt])
  if (loading) return <LoadState busy error="" retry={() => {}}/>
  if (!user) return <Navigate to="/login" replace state={{ from: location.pathname + location.search }}/>
  async function start() {
    setBusy(true); setError('')
    try { setAttempt(await cent.startExam(kind, requestId.current, course || undefined, topic || undefined)); setIndex(0); setAnswers({}) }
    catch (e) { setError(e instanceof Error ? e.message : 'آزمون آماده نشد.') } finally { setBusy(false) }
  }
  async function submit() {
    if (!attempt) return
    setBusy(true); setError('')
    try {
      const outcome = await cent.submitExam(attempt.id, answers)
      setDiagnostic(outcome.result, outcome.analysis)
      sessionStorage.removeItem(storageKey)
      navigate(`/student/results/${attempt.id}${returnToStudy ? `?returnTo=${encodeURIComponent(returnToStudy)}` : ''}`)
    } catch (e) { setError(e instanceof Error ? e.message : 'ثبت نتیجه انجام نشد؛ پاسخ‌هایت حفظ شده‌اند.'); setBusy(false) }
  }
  const question = attempt?.questions[index]
  return <div className="container cent-exam">{kind === 'diagnostic' && <div className="standalone-appearance"><AppearanceControl/></div>}<Link className="back-link" to={returnToStudy || "/student"}>{returnToStudy ? "بازگشت به مطالعه" : "بازگشت به پنل"}</Link><PageHeader eyebrow="سنجش مسیر" title={kind === 'diagnostic' ? 'آزمون تعیین سطح' : kind === 'practice' ? 'تمرین مبحث' : 'آزمون شبیه‌ساز'} description="نتیجه از پاسخ‌ها و کلید پاسخ سرور محاسبه می‌شود."/>{error && <p className="inline-error" role="alert">{error}</p>}{!attempt ? <section className="card cent-admin-panel"><h2>با آرامش شروع کن</h2><label className="cent-section-select">درس<select aria-label="انتخاب درس" value={course} onChange={e => { setCourse(e.target.value); setTopic(''); requestId.current = crypto.randomUUID() }}><option value="">همه درس‌ها</option>{catalog.data?.courses.map(c => <option key={c.code} value={c.code}>{c.title}</option>)}</select></label><label className="cent-section-select">مبحث<select aria-label="انتخاب مبحث" value={topic} onChange={e => { setTopic(e.target.value); requestId.current = crypto.randomUUID() }}><option value="">همه مباحث</option>{catalog.data?.topics.filter(t => !course || t.courseCode === course).map(t => <option key={t.id} value={t.id}>{t.title}</option>)}</select></label><LoadState {...catalog} retry={catalog.reload}/><p>برای هر تلاش ۶۰ دقیقه زمان داری. پاسخ‌ها تا زمان ثبت در همین مرورگر حفظ می‌شوند. شبیه‌ساز به اشتراک فعال نیاز دارد.</p><button className="button button-primary" disabled={busy} onClick={start}>{busy ? 'در حال آماده‌سازی…' : 'شروع آزمون'}<ArrowLeft size={16}/></button></section> : question && <><div className="cent-exam-status"><span>سؤال {index + 1} از {attempt.questions.length}</span><span><Clock3 size={16}/> {Math.floor(remaining / 60)}:{String(remaining % 60).padStart(2, '0')}</span></div><ProgressBar value={100 * Object.keys(answers).length / attempt.questions.length}/><div className="cent-exam-dots">{attempt.questions.map((q, i) => <button className={i === index ? 'active' : answers[q.id] != null ? 'answered' : ''} key={q.id} onClick={() => setIndex(i)}>{i + 1}</button>)}</div><section className="card sim-question"><span className="eyebrow">{question.topic}</span><span className="cent-tag">{({ easy: 'آسان', medium: 'متوسط', hard: 'سخت' })[question.difficulty]}</span><h2 dir="auto">{question.text}</h2>{question.figureSvg && <img className="cent-question-figure" alt="شکل سؤال" src={`data:image/svg+xml;charset=utf-8,${encodeURIComponent(question.figureSvg)}`}/>}<div className="options-list">{question.options.map((option, i) => <button key={i} disabled={busy || remaining <= 0} className={answers[question.id] === i ? 'selected' : ''} onClick={() => setAnswers(a => ({ ...a, [question.id]: i }))}><span>{['الف', 'ب', 'ج', 'د', 'هـ', 'و'][i]}</span><b dir="auto">{option}</b></button>)}</div><div className="question-actions"><button className="button button-ghost" disabled={index <= 0} onClick={() => setIndex(i => i - 1)}><ArrowRight size={16}/> قبلی</button><button className="button button-ghost" onClick={() => setAnswers(a => ({ ...a, [question.id]: null }))}>پاک‌کردن پاسخ</button>{index < attempt.questions.length - 1 ? <button className="button button-secondary" onClick={() => setIndex(i => i + 1)}>بعدی <ArrowLeft size={16}/></button> : <button className="button button-primary" disabled={busy || remaining <= 0} onClick={submit}>{busy ? 'در حال ثبت…' : 'ثبت و دیدن نتیجه'}</button>}</div>{remaining <= 0 && <p className="notice">زمان آزمون پایان یافته است. <button className="button button-ghost" onClick={() => { sessionStorage.removeItem(storageKey); requestId.current = crypto.randomUUID(); setAttempt(null) }}>آزمون تازه</button></p>}</section></>}</div>
}

export function CentResultsPage() {
  return <PersonalResults/>
}

export function CentResultPage() {
  const { id = '' } = useParams()
  const [params] = useSearchParams()
  const returnToStudy = studyReturnPath(params.get('returnTo'))
  const fetcher = useCallback<() => Promise<ExamOutcome>>(() => cent.outcome(id), [id])
  const remote = useRemote(fetcher)
  const outcome = remote.data
  return <><PageHeader title="گزارش آزمون" action={<Link className="button button-secondary" to="/student/results">همه نتایج</Link>}/><LoadState {...remote} retry={remote.reload}/>{outcome && <><div className="stats-grid"><StatCard label="درصد کل" value={`${outcome.result.percentage}٪`} icon={<Target/>}/><StatCard label="صحیح" value={outcome.result.correct} icon={<CheckCircle2/>}/><StatCard label="نادرست" value={outcome.result.incorrect} icon={<ArrowLeft/>}/><StatCard label="بدون پاسخ" value={outcome.result.unanswered} icon={<Clock3/>}/></div><section className="card cent-admin-panel"><h2>قدم بعدی تو</h2><p>{outcome.analysis.suggestedNextStep}</p><div className="cent-tag-row">{outcome.analysis.priorityTopics.map(t => <span className="cent-tag" key={t}>{t}</span>)}</div><p className="muted-text">{outcome.analysis.personalizedExplanation}</p><Link className="button button-primary" to={returnToStudy || "/student/content"}>{returnToStudy ? "بازگشت به مطالعه" : "رفتن به مطالعه"}</Link></section><div className="cent-admin-columns"><section className="card cent-admin-panel"><h2>عملکرد موضوعی</h2><Link className="text-link" to="/student/analysis">نقشه یادگیری و تسلط همه مباحث</Link>{Object.entries(outcome.result.byTopic).map(([topic, result]) => <div className="chapter-progress" key={topic}><div><b>{topic}</b><span>{result.correct} از {result.total}</span></div><strong>{result.percentage}٪</strong><ProgressBar value={result.percentage}/></div>)}</section><section className="card cent-admin-panel"><h2>مرور پاسخ‌ها</h2>{outcome.review.map((q, i) => <details className="cent-answer-review" key={q.id}><summary>سؤال {i + 1} · {q.topic} · {outcome.result.answers[q.id] == null ? 'بی‌پاسخ' : outcome.result.answers[q.id] === q.correctAnswer ? 'صحیح' : 'نادرست'}</summary><p>گزینه صحیح: {q.correctAnswer + 1}</p><p dir="auto">{q.explanation}</p></details>)}</section></div></>}</>
}

export function CentSimulatorsPage() {
  const { hasPackage } = useAppState()
  return <><PageHeader title="آزمون شبیه‌ساز" description="بعد از مطالعه، خودت را دوباره بسنج."/><section className="card cent-admin-panel"><h2>مرور ترکیبی درس‌ها</h2><p>آزمون از سؤال‌های منتشرشده ساخته می‌شود و گزارش موضوعی آن در حساب شما باقی می‌ماند.</p><Link className="button button-primary" to={hasPackage ? '/student/simulators/test' : '/package'}>{hasPackage ? 'شروع شبیه‌ساز' : 'انتخاب اشتراک مطالعه'}<ArrowLeft size={16}/></Link></section></>
}

import { useCallback, useEffect, useRef, useState } from 'react'
import { Link, useParams, useSearchParams } from 'react-router-dom'
import { ArrowLeft, ArrowRight, BookOpen, Check, ChevronLeft, Maximize2, MessageSquare, Minus, Plus, Save, Trash2, X } from 'lucide-react'
import { cent, type StudyNote, type SourceSection } from '../services/cent'
import { useAppState } from '../state/AppState'
import { LoadState, useRemote } from '../components/CentUI'
import { AppearanceControl } from '../components/AppearanceControl'

export function StudyReader() {
  const { id = '' } = useParams()
  return <Reader key={id} id={id}/>
}
function Reader({ id }: { id: string }) {
  const fetcher = useCallback(() => cent.document(id), [id])
  const remote = useRemote(fetcher)
  const { user } = useAppState()
  const [params] = useSearchParams()
  const [sourceSections, setSourceSections] = useState<SourceSection[]>([])
  const [page, setPage] = useState(0)
  const [zoom, setZoom] = useState(100)
  const [notes, setNotes] = useState<StudyNote[]>([])
  const [editing, setEditing] = useState<StudyNote | null>(null)
  const [draft, setDraft] = useState('')
  const [anchorY, setAnchorY] = useState(0.15)
  const [saveState, setSaveState] = useState('')
  const [saving, setSaving] = useState(false)
  const [pageBusy, setPageBusy] = useState(false)
  const [pageError, setPageError] = useState('')
  const [retryPage, setRetryPage] = useState(0)
  const [notesOpen, setNotesOpen] = useState(true)
  const [hidden, setHidden] = useState(document.hidden)
  const canvas = useRef<HTMLCanvasElement>(null)
  const newNoteId = useRef<string>(crypto.randomUUID())
  const pageStage = useRef<HTMLDivElement>(null)
  const draftKey = `cent:draft:${user?.id}:${id}:${page}`
  const dirty = draft.trim().length > 0 && draft !== editing?.body

  useEffect(() => {
    if (!remote.data) return
    const requested = Number(params.get('page'))
    setPage(Number.isInteger(requested) && requested >= 1 && requested <= remote.data.document.pageCount ? requested : remote.data.progress?.lastPage || 1)
    setNotes(remote.data.notes)
  }, [remote.data, params])

  useEffect(() => {
    if (!page) return
    newNoteId.current = crypto.randomUUID()
    setEditing(null); setAnchorY(0.15); setSaveState('')
    try { setDraft(localStorage.getItem(draftKey) || '') } catch { setDraft('') }
  }, [draftKey, page])

  useEffect(() => {
    const handle = (event: BeforeUnloadEvent) => { if (dirty) { event.preventDefault(); event.returnValue = '' } }
    const visibility = () => setHidden(document.hidden)
    window.addEventListener('beforeunload', handle); document.addEventListener('visibilitychange', visibility)
    return () => { window.removeEventListener('beforeunload', handle); document.removeEventListener('visibilitychange', visibility) }
  }, [dirty])

  const watermark = remote.data?.watermark
  const sourceId = remote.data?.document.sourceId
  useEffect(() => {
    if (!sourceId) return
    let disposed = false
    setPageBusy(true); setPageError('')
    cent.sourceSections(id).then(rows => { if (!disposed) setSourceSections(rows) }).catch(e => { if (!disposed) setPageError(e.message) }).finally(() => { if (!disposed) setPageBusy(false) })
    return () => { disposed = true }
  }, [id, sourceId, retryPage])
  useEffect(() => {
    if (!page || !watermark || sourceId) return
    const controller = new AbortController()
    let url: string | undefined
    let disposed = false
    setPageBusy(true); setPageError('')
    const surface = canvas.current
    if (surface) { const ctx = surface.getContext('2d'); ctx?.clearRect(0, 0, surface.width, surface.height) }
    cent.page(id, page, controller.signal).then(blob => new Promise<HTMLImageElement>((resolve, reject) => {
      const image = new Image(); url = URL.createObjectURL(blob)
      image.onload = () => resolve(image); image.onerror = () => reject(new Error('تصویر صفحه قابل نمایش نیست.')); image.src = url
    })).then(image => {
      if (disposed || !surface) return
      const ctx = surface.getContext('2d')!
      surface.width = image.naturalWidth; surface.height = image.naturalHeight
      ctx.drawImage(image, 0, 0)
      ctx.save(); ctx.globalAlpha = 0.17; ctx.fillStyle = '#294251'
      ctx.font = `${Math.max(15, surface.width / 48)}px sans-serif`; ctx.textAlign = 'center'
      for (let y = 120; y < surface.height; y += Math.max(240, surface.height / 4)) {
        for (let x = surface.width / 4; x < surface.width; x += surface.width / 2) {
          ctx.save(); ctx.translate(x, y); ctx.rotate(-Math.PI / 8); ctx.fillText(watermark, 0, 0); ctx.restore()
        }
      }
      ctx.restore()
    }).catch(e => { if (!disposed && !controller.signal.aborted) setPageError(e instanceof Error ? e.message : 'صفحه بارگذاری نشد.') })
      .finally(() => { if (url) URL.revokeObjectURL(url); if (!disposed) setPageBusy(false) })
    return () => { disposed = true; controller.abort(); if (url) URL.revokeObjectURL(url) }
  }, [id, page, watermark, retryPage, sourceId])

  useEffect(() => {
    if (!page || pageBusy || pageError) return
    const timer = window.setTimeout(() => { void cent.progress(id, page).catch(() => setSaveState('محل مطالعه ذخیره نشد؛ اتصال را بررسی کنید.')) }, 1200)
    return () => window.clearTimeout(timer)
  }, [id, page, pageBusy, pageError])

  function updateDraft(value: string) {
    setDraft(value); setSaveState('پیش‌نویس روی این دستگاه')
    try { localStorage.setItem(draftKey, value) } catch { setSaveState('پیش‌نویس ذخیره نشد؛ پیش از خروج ثبت کنید.') }
  }
  function resetNoteEditor() {
    newNoteId.current = crypto.randomUUID()
    setEditing(null); setDraft(''); setAnchorY(0.15); setSaveState('')
    try { localStorage.removeItem(draftKey) } catch { /* The editor can still create a new note. */ }
  }
  function startNewNote() {
    if (saving) return
    if (dirty && !window.confirm('نوشته ثبت‌نشده با یادداشت جدید جایگزین شود؟')) return
    resetNoteEditor()
  }
  async function save() {
    if (!draft.trim() || saving) return
    setSaving(true); setSaveState('در حال ذخیره…')
    try {
      const note = await cent.saveNote({ id: editing?.id || newNoteId.current, documentId: id, page, anchorY, body: draft, revision: editing?.revision || 0 })
      setNotes(current => [...current.filter(n => n.id !== note.id), note]); setEditing(note); setDraft(note.body)
      localStorage.removeItem(draftKey); setSaveState('در حساب شما ذخیره شد')
    } catch (e) { setSaveState(e instanceof Error ? e.message : 'ذخیره انجام نشد؛ پیش‌نویس شما باقی مانده است.') }
    finally { setSaving(false) }
  }
  async function remove(note: StudyNote) {
    if (!window.confirm('این یادداشت حذف شود؟')) return
    try { await cent.deleteNote(note); setNotes(current => current.filter(n => n.id !== note.id)); if (editing?.id === note.id) resetNoteEditor(); setSaveState('یادداشت حذف شد') }
    catch (e) { setSaveState(e instanceof Error ? e.message : 'حذف انجام نشد.') }
  }
  function selectNote(note: StudyNote) {
    if (saving) return
    if (dirty && !window.confirm('نوشته ثبت‌نشده با این یادداشت جایگزین شود؟')) return
    setEditing(note); setDraft(note.body); setAnchorY(note.anchorY); setSaveState('')
  }
  function changePage(next: number) { if (saving) return; setPage(next); pageStage.current?.scrollIntoView({ behavior: 'smooth', block: 'start' }) }
  const currentNotes = notes.filter(n => n.page === page).sort((a, b) => a.anchorY - b.anchorY)
  return <div className={`cent-reader ${notesOpen ? '' : 'notes-closed'}`}><header className="cent-reader-header"><AppearanceControl/><Link to="/student/content"><ArrowRight size={18}/> کتابخانه من</Link><div><span>فضای مطالعه</span><h1>{remote.data?.document.title || 'آموزش'}</h1></div><button className="button button-secondary button-small" onClick={() => setNotesOpen(o => !o)}><MessageSquare size={16}/> یادداشت‌ها</button></header><LoadState {...remote} retry={remote.reload}/>{remote.error && <Link className="button button-primary" to="/package">خرید یا تمدید دسترسی</Link>}{remote.data && <><div className="cent-reader-toolbar"><div className="cent-reader-pagination"><button aria-label="صفحه قبل" disabled={page <= 1 || saving} onClick={() => changePage(page - 1)}><ArrowRight size={18}/></button><label>صفحه <select aria-label="انتخاب صفحه" value={page} onChange={e => changePage(Number(e.target.value))}>{Array.from({ length: remote.data.document.pageCount }, (_, i) => <option key={i + 1} value={i + 1}>{i + 1}</option>)}</select> از {remote.data.document.pageCount}</label><button aria-label="صفحه بعد" disabled={page >= remote.data.document.pageCount || saving} onClick={() => changePage(page + 1)}><ArrowLeft size={18}/></button></div><div className="cent-reader-zoom"><button aria-label="کوچک‌نمایی" disabled={zoom <= 75} onClick={() => setZoom(z => z - 25)}><Minus size={16}/></button><span>{zoom}٪</span><button aria-label="بزرگ‌نمایی" disabled={zoom >= 200} onClick={() => setZoom(z => z + 25)}><Plus size={16}/></button><button aria-label="اندازه معمول" onClick={() => setZoom(100)}><Maximize2 size={16}/></button></div></div><div className="cent-reader-layout"><main className="cent-reading-area" ref={pageStage}><div className="cent-page-shell" style={{ width: `${zoom}%` }} onContextMenu={e => e.preventDefault()}><div className={`cent-page-content ${hidden || pageBusy || pageError ? 'concealed' : ''}`} onClick={e => {
    const bounds = e.currentTarget.getBoundingClientRect(); setAnchorY(Math.max(0, Math.min(1, (e.clientY - bounds.top) / bounds.height))); setNotesOpen(true)
  }}>{sourceId && <article className="cent-source-text"><small>{watermark}</small><h2>{sourceSections[page - 1]?.heading}</h2><div>{sourceSections[page - 1]?.text}</div>{sourceSections[page - 1]?.topicId && <Link className="button button-secondary" to={`/student/practice?topic=${sourceSections[page - 1].topicId}&returnTo=${encodeURIComponent(`/student/study/${id}?page=${page}`)}`}>تمرین این مبحث</Link>}</article>}<canvas hidden={!!sourceId} ref={canvas} role="img" aria-label={`صفحه ${page} از ${remote.data.document.title}`} draggable={false}/>{currentNotes.map((note, i) => <button key={note.id} className={`cent-note-pin ${editing?.id === note.id ? 'selected' : ''}`} style={{ top: `${note.anchorY * 100}%` }} aria-label={`یادداشت ${i + 1}`} onClick={e => { e.stopPropagation(); selectNote(note); setNotesOpen(true) }}>{i + 1}</button>)}</div>{(pageBusy || pageError) && <div className="cent-page-overlay"><LoadState busy={pageBusy} error={pageError} retry={() => setRetryPage(x => x + 1)}/>{pageError && <Link to="/package">بررسی دسترسی</Link>}</div>}</div><div className="cent-page-footer"><span><BookOpen size={14}/> صفحه {page} · برای ثبت نکته روی بخش موردنظر بزن</span><span>نمایش شخصی برای {user?.name}</span></div></main><aside className="cent-reader-notes"><div className="cent-reader-notes-title"><div><MessageSquare size={18}/><h2>کنار این صفحه</h2><span>{currentNotes.length}</span></div><button className="icon-button" aria-label="بستن یادداشت‌ها" onClick={() => setNotesOpen(false)}><X size={16}/></button></div>{remote.data.sections.length > 0 && <label className="cent-section-select">فهرست درس<select value={remote.data.sections.filter(s => s.startPage <= page).at(-1)?.startPage || ''} onChange={e => changePage(Number(e.target.value))}><option value="" disabled>انتخاب بخش</option>{remote.data.sections.map(s => <option key={`${s.startPage}:${s.title}`} value={s.startPage}>{s.title} · صفحه {s.startPage}</option>)}</select></label>}<div className="cent-note-editor"><span className="eyebrow">{editing ? 'ویرایش یادداشت' : 'نکته تازه'} · صفحه {page}</span><textarea disabled={saving} aria-label="متن یادداشت" placeholder="اینجا چه چیزی یاد گرفتی؟ سؤالت چیست؟" maxLength={4000} value={draft} onChange={e => updateDraft(e.target.value)}/><label className="cent-anchor-label">محل یادداشت روی صفحه<input disabled={saving} type="range" min="0" max="100" value={Math.round(anchorY * 100)} onChange={e => setAnchorY(Number(e.target.value) / 100)}/></label><div className="cent-note-editor-actions"><button className="button button-primary button-small" disabled={!draft.trim() || saving} onClick={save}>{saveState === 'در حساب شما ذخیره شد' ? <Check size={15}/> : <Save size={15}/>} {saving ? 'در حال ثبت…' : 'ثبت یادداشت'}</button>{editing && <button className="button button-ghost button-small" disabled={saving} onClick={startNewNote}>یادداشت جدید</button>}</div><small role="status" className="cent-save-status">{saveState || 'یادداشت‌ها فقط برای خودت قابل مشاهده‌اند.'}</small></div><div className="cent-page-notes">{currentNotes.length === 0 && <div className="cent-notes-empty"><MessageSquare/><p>اولین فکر کنار این صفحه را بنویس.</p></div>}{currentNotes.map((note, i) => <article key={note.id} className={editing?.id === note.id ? 'active' : ''}><button className="cent-note-text" onClick={() => selectNote(note)}><span>یادداشت {i + 1} <ChevronLeft size={14}/></span><p>{note.body}</p></button><button className="cent-note-delete" disabled={saving} aria-label="حذف یادداشت" onClick={() => remove(note)}><Trash2 size={14}/></button></article>)}</div><Link className="text-link" to="/student/notes">همه یادداشت‌های من <ArrowLeft size={15}/></Link></aside></div></>}</div>
}
